mapper.select:
/* SQL ID : DscsJoinUserDAO.listPaging 설명 : 토론 참여자 페이징 목록 조회 */ SELECT
ROW_NUMBER() OVER(ORDER BY LENGTH(teamnm), teamnm, userNm) AS LINE_NO
ROW_NUMBER() OVER(ORDER BY userNm) AS LINE_NO
, dscsId , deptNm , stdntNo , userId , userNm , scr , evlyn , scrNull , (CASE WHEN actlCnt > 0 THEN '참여완료' ELSE '미참여' END) AS joinStatus , actlCnt , cmntCnt , teamId , dscsId , COUNT(1) OVER() AS totalCnt , dscsFdbkId , dscsFdbkCts , oknokGbnCd , (CASE WHEN actlCnt > 0 THEN regDttm ELSE '-' END) AS regDttm , profMemo , teamnm , CASE WHEN memberRole = 'Y' THEN '팀장' ELSE '팀원' END AS memberRole , mobileNo , email , dscsMyAtclCnt , dscsAtclCnt , dscsMyCmntCnt , dscsCmntCnt , SCYR , ENTR_YY , ENTR_HY , ENTR_GBN , ENTR_GBN_NM FROM ( SELECT NVL(CD.DSCS_ID, C.DSCS_ID) AS dscsId , NVL((SELECT D.DEPTNM FROM TB_LMS_DEPT D WHERE D.DEPT_ID = U.DEPT_ID), '-') AS DEPTNM , U.STDNT_NO AS stdntNo , U.USERNM AS userNm , NVL(P.SCR, 0) AS scr , NVL(P.EVLYN, 'N') AS evlyn , NVL(TO_CHAR(P.SCR), '-') AS scrNull , (SELECT COUNT(*) FROM TB_LMS_DSCS_ATCL B WHERE B.DSCS_ID = NVL(CD.DSCS_ID, C.DSCS_ID) AND B.RGTR_ID = A.USER_ID AND B.DELYN = 'N' ) AS actlCnt , (SELECT COUNT(*) FROM TB_LMS_DSCS_CMNT B JOIN TB_LMS_DSCS_ATCL AA ON B.DSCS_ATCL_ID = AA.DSCS_ATCL_ID WHERE AA.DSCS_ID = NVL(CD.DSCS_ID, C.DSCS_ID) AND B.RGTR_ID = A.USER_ID AND B.DELYN = 'N') AS cmntCnt , U.USER_ID as userId , TM.TEAM_ID AS teamId , (SELECT MIN(DSCS_FDBK_ID) KEEP (DENSE_RANK FIRST ORDER BY MOD_DTTM) FROM TB_LMS_DSCS_FDBK B WHERE B.DSCS_ID = NVL(CD.DSCS_ID, C.DSCS_ID) AND B.USER_ID = A.USER_ID AND B.DELYN = 'N' AND B.UP_DSCS_FDBK_ID IS NULL) AS dscsFdbkId , (SELECT B.DSCS_FDBK_CTS FROM TB_LMS_DSCS_FDBK B WHERE B.DSCS_ID = NVL(CD.DSCS_ID, C.DSCS_ID) AND B.USER_ID = A.USER_ID AND B.DELYN = 'N' AND B.UP_DSCS_FDBK_ID IS NULL AND B.MOD_DTTM = (SELECT MAX(MOD_DTTM) FROM TB_LMS_DSCS_FDBK WHERE DSCS_ID = NVL(CD.DSCS_ID, C.DSCS_ID) AND USER_ID = A.USER_ID AND DELYN = 'N' AND UP_DSCS_FDBK_ID IS NULL) AND ROWNUM = 1) AS dscsFdbkCts , P.REG_DTTM AS regDttm , P.PROF_MEMO AS profMemo , TM.TEAMNM AS teamnm , TM.LDRYN AS memberRole , (SELECT MAX(CNTCT) FROM TB_LMS_USER_CNTCT T1 WHERE T1.USER_ID = A.USER_ID AND T1.CNTCT_TYCD = 'MBL_PHN') AS mobileNo , (SELECT MAX(CNTCT) FROM TB_LMS_USER_CNTCT T1 WHERE T1.USER_ID = A.USER_ID AND T1.CNTCT_TYCD = 'INDV_EML') AS email , (SELECT COUNT(*) FROM TB_LMS_DSCS_ATCL WHERE DSCS_ID = NVL(CD.DSCS_ID, C.DSCS_ID) AND DELYN = 'N' AND RGTR_ID = A.USER_ID) AS dscsMyAtclCnt , (SELECT COUNT(*) FROM TB_LMS_DSCS_ATCL WHERE DSCS_ID = NVL(CD.DSCS_ID, C.DSCS_ID) AND DELYN = 'N') AS dscsAtclCnt , (SELECT COUNT(*) FROM TB_LMS_DSCS_CMNT WHERE DELYN = 'N' AND RGTR_ID = A.USER_ID AND DSCS_ATCL_ID IN (SELECT CX.DSCS_ATCL_ID FROM TB_LMS_DSCS_ATCL CX WHERE CX.DSCS_ID = NVL(CD.DSCS_ID, C.DSCS_ID) AND CX.DELYN = 'N')) AS dscsMyCmntCnt , (SELECT COUNT(*) FROM TB_LMS_DSCS_CMNT WHERE DELYN = 'N' AND DSCS_ATCL_ID IN (SELECT CX.DSCS_ATCL_ID FROM TB_LMS_DSCS_ATCL CX WHERE CX.DSCS_ID = NVL(CD.DSCS_ID, C.DSCS_ID) AND CX.DELYN = 'N')) AS dscsCmntCnt , CASE WHEN C.DSCS_UNIT_TYCD != 'TEAM' AND C.OKNOK_STNGYN = 'Y' THEN NVL((SELECT B.OKNOK_GBNCD FROM TB_LMS_DSCS_ATCL B WHERE B.DSCS_ID = NVL(CD.DSCS_ID, C.DSCS_ID) AND B.RGTR_ID = A.USER_ID AND B.DELYN = 'N' AND ROWNUM = 1), '-') ELSE '-' END AS oknokGbnCd , NVL(TO_CHAR(A.SCYR), '-') AS SCYR , '-' AS ENTR_YY, '-' AS ENTR_HY, '-' AS ENTR_GBN, '-' AS ENTR_GBN_NM FROM TB_LMS_ATNDLC A JOIN TB_LMS_DSCS C ON C.DSCS_ID = #{dscsId} AND C.DELYN = 'N' JOIN TB_LMS_USER U ON A.USER_ID = U.USER_ID
/* ORA-01799 해결: 인라인 뷰를 사용하여 팀 정보 조인 */ LEFT JOIN ( SELECT M.USER_ID, M.TEAM_ID, M.LDRYN, T.TEAMNM, T.TEAM_GRP_ID FROM TB_LMS_TEAM_MBR M JOIN TB_LMS_TEAM T ON M.TEAM_ID = T.TEAM_ID /* 현재 토론의 팀그룹(TEAM_GRP_ID) 내 팀만 선택하여 타 과목 팀 오매칭 방지 */ WHERE (M.USER_ID, M.TEAM_ID) IN ( SELECT MBR.USER_ID, MAX(MBR.TEAM_ID) FROM TB_LMS_TEAM_MBR MBR JOIN TB_LMS_TEAM TM2 ON MBR.TEAM_ID = TM2.TEAM_ID WHERE TM2.TEAM_GRP_ID = ( SELECT TEAM_GRP_ID FROM TB_LMS_DSCS WHERE DSCS_ID = #{dscsId} AND DELYN = 'N' AND ROWNUM = 1 ) GROUP BY MBR.USER_ID ) ) TM ON TM.USER_ID = A.USER_ID AND TM.TEAM_GRP_ID = C.TEAM_GRP_ID
AND TM.TEAM_ID = #{teamId}
LEFT JOIN TB_LMS_DSCS CD ON CD.UP_DSCS_ID = C.DSCS_ID AND CD.TEAM_ID = TM.TEAM_ID AND CD.DELYN = 'N' LEFT JOIN TB_LMS_DSCS_PTCP P ON P.DSCS_ID = NVL(CD.DSCS_ID, C.DSCS_ID) AND P.USER_ID = A.USER_ID WHERE A.SBJCT_ID = #{sbjctId} AND A.ATNDLC_STSCD = 'APPROVE' AND A.AUDITYN = 'N' ) T
AND teamId = #{teamId}
AND actlCnt > 0 AND actlCnt = 0 AND memberRole = 'Y' AND memberRole != 'Y'
AND scrNull != '-' AND scrNull = '-'
AND ( LOWER(deptNm) LIKE '%' || LOWER(#{searchValue}) || '%' OR LOWER(userId) LIKE '%' || LOWER(#{searchValue}) || '%' OR LOWER(userNm) LIKE '%' || LOWER(#{searchValue}) || '%' )
ORDER BY LINE_NO ASC

mapper.insert:
/* SQL ID : DscsJoinUserDAO.insertStdScore 설명 : 토론 참여자 점수 반영 */ MERGE INTO TB_LMS_DSCS_PTCP T USING ( SELECT
#{stdId} AS USER_ID
#{userId} AS USER_ID
, #{dscsId} AS DSCS_ID FROM DUAL ) S ON ( T.USER_ID = S.USER_ID AND T.DSCS_ID = S.DSCS_ID ) WHEN MATCHED THEN UPDATE SET T.SCR = CASE WHEN CAST(#{scr} AS NUMBER) < 0 THEN 0 WHEN CAST(#{scr} AS NUMBER) > 100 THEN 100 ELSE CAST(#{scr} AS NUMBER) END, T.TEAM_ID = #{teamId}, T.EVLYN = 'Y', T.MDFR_ID = #{mdfrId}, T.MOD_DTTM = FN_DTTM() WHEN NOT MATCHED THEN INSERT ( DSCS_PTCP_ID, USER_ID, DSCS_ID, TEAM_ID, SCR, EVLYN, RGTR_ID, REG_DTTM, MDFR_ID, MOD_DTTM, DELYN ) VALUES ( #{dscsPtcpId},
#{stdId}
#{userId}
, #{dscsId}, #{teamId}, CASE WHEN CAST(#{scr} AS NUMBER) < 0 THEN 0 WHEN CAST(#{scr} AS NUMBER) > 100 THEN 100 ELSE CAST(#{scr} AS NUMBER) END, 'Y', #{rgtrId}, FN_DTTM(), #{mdfrId}, FN_DTTM(), 'N' )

/* SQL ID : DscsJoinUserDAO.insertStdScoreBatch 설명 : 토론 참여 점수 배치 반영 */ MERGE INTO TB_LMS_DSCS_PTCP T USING (
SELECT #{item.dscsPtcpId} AS DSCS_PTCP_ID,
#{item.stdId} AS USER_ID
#{item.userId} AS USER_ID
, #{item.dscsId} AS DSCS_ID, #{item.teamId} AS TEAM_ID, CAST(#{item.scr} AS NUMBER) AS SCR, #{item.rgtrId} AS RGTR_ID, #{item.mdfrId} AS MDFR_ID FROM DUAL
) S ON ( T.USER_ID = S.USER_ID AND T.DSCS_ID = S.DSCS_ID ) WHEN MATCHED THEN UPDATE SET T.SCR = CASE WHEN S.SCR < 0 THEN 0 WHEN S.SCR > 100 THEN 100 ELSE S.SCR END, T.TEAM_ID = S.TEAM_ID, T.EVLYN = 'Y', T.MDFR_ID = S.MDFR_ID, T.MOD_DTTM = FN_DTTM() WHEN NOT MATCHED THEN INSERT ( DSCS_PTCP_ID, USER_ID, DSCS_ID, TEAM_ID, SCR, EVLYN, RGTR_ID, REG_DTTM, MDFR_ID, MOD_DTTM, DELYN ) VALUES ( S.DSCS_PTCP_ID, S.USER_ID, S.DSCS_ID, S.TEAM_ID, CASE WHEN S.SCR < 0 THEN 0 WHEN S.SCR > 100 THEN 100 ELSE S.SCR END, 'Y', S.RGTR_ID, FN_DTTM(), S.MDFR_ID, FN_DTTM(), 'N' )

mapper.select:
/* SQL ID : DscsJoinUserDAO.listStdScore 설명 : 토론 참여자 점수 등록 대상 목록 조회 */ SELECT ROW_NUMBER() OVER(ORDER BY stdId ASC) AS lineNo , stdId , scr , CASE WHEN atclCnt > 0 OR cmntCnt > 0 THEN '참여' ELSE '미참여' END AS joinStatus , atclCnt , cmntCnt , teamId , dscsId FROM ( SELECT A.USER_ID AS stdId , NVL(C.SCR, 0) AS scr /* 팀토론 PTCP row가 없을 때도 자식토론의 TEAM_ID를 점수 처리 대상으로 사용 */ , NVL(C.TEAM_ID, TM_CD.TEAM_ID) AS teamId , NVL(TM_CD.CD_DSCS_ID, #{dscsId}) AS dscsId /* 결정된 targetDscsId를 사용하여 게시글 수 조회 */ , (SELECT COUNT(*) FROM TB_LMS_DSCS_ATCL B WHERE B.DSCS_ID = NVL(TM_CD.CD_DSCS_ID, #{dscsId}) AND B.RGTR_ID = A.USER_ID AND B.DELYN = 'N') AS atclCnt /* 결정된 targetDscsId를 사용하여 댓글 수 조회 */ , (SELECT COUNT(*) FROM TB_LMS_DSCS_CMNT B JOIN TB_LMS_DSCS_ATCL AA ON B.DSCS_ATCL_ID = AA.DSCS_ATCL_ID WHERE AA.DSCS_ID = NVL(TM_CD.CD_DSCS_ID, #{dscsId}) AND B.RGTR_ID = A.USER_ID AND B.DELYN = 'N') AS cmntCnt /* 필터링을 위한 USER_ID 유지 */ , A.USER_ID FROM TB_LMS_ATNDLC A
/* [해결책] ORA-01799 방지: 사용자별 자식 토론 ID를 미리 매칭해두는 인라인 뷰 */ LEFT JOIN ( SELECT TM2.USER_ID, CD2.DSCS_ID AS CD_DSCS_ID, CD2.TEAM_ID AS TEAM_ID FROM TB_LMS_DSCS CD2 JOIN TB_LMS_TEAM_MBR TM2 ON TM2.TEAM_ID = CD2.TEAM_ID WHERE CD2.UP_DSCS_ID = #{dscsId} AND CD2.DELYN = 'N' ) TM_CD ON A.USER_ID = TM_CD.USER_ID
/* 참여 정보 조인: 위에서 매칭된 자식 ID가 있으면 그것을, 없으면 부모 ID를 사용 */ LEFT JOIN TB_LMS_DSCS_PTCP C ON A.USER_ID = C.USER_ID AND C.DSCS_ID = NVL(TM_CD.CD_DSCS_ID, #{dscsId})
WHERE A.SBJCT_ID = #{sbjctId} AND A.ATNDLC_STSCD = 'APPROVE' ) T
AND USER_ID IN
#{item}
AND ( atclCnt > 0 OR cmntCnt > 0 )
AND ( atclCnt = 0 AND cmntCnt = 0 )
AND USER_ID = #{stdId}

/* SQL ID : DscsJoinUserDAO.listStdScoreByTargets 설명 : 점수 처리 대상 현재 점수 조회 */ SELECT S.USER_ID AS stdId , S.DSCS_ID AS dscsId /* 신규 점수 row 생성 시 전달받은 팀ID를 유지 */ , NVL(P.TEAM_ID, S.TEAM_ID) AS teamId , NVL(P.SCR, 0) AS scr FROM (
SELECT #{item.stdId} AS USER_ID , #{item.dscsId} AS DSCS_ID , #{item.teamId} AS TEAM_ID FROM DUAL
) S LEFT JOIN TB_LMS_DSCS_PTCP P ON P.USER_ID = S.USER_ID AND P.DSCS_ID = S.DSCS_ID

/* SQL ID : DscsJoinUserDAO.listCtsLenScoreTargets 설명 : 글자수 기준 점수 처리 대상 조회 */ SELECT DISTINCT S.USER_ID AS stdId , S.DSCS_ID AS dscsId , S.TEAM_ID AS teamId FROM (
SELECT #{item.stdId} AS USER_ID , #{item.dscsId} AS DSCS_ID , #{item.teamId} AS TEAM_ID FROM DUAL
) S JOIN TB_LMS_DSCS_ATCL A ON A.DSCS_ID = S.DSCS_ID AND A.RGTR_ID = S.USER_ID AND A.DELYN = 'N'
LEFT JOIN TB_LMS_DSCS_CMNT C ON C.DSCS_ATCL_ID = A.DSCS_ATCL_ID AND C.USER_ID = S.USER_ID AND C.DELYN = 'N'
WHERE A.ATCL_CTS_LEN >= #{ctsLen}
OR C.CMNT_CTS_LEN >= #{ctsLen}

mapper.update:
/*
	SQL ID : DscsJoinUserDAO.editDscsProfMemo
	설명 : 교수 메모 수정
*/
UPDATE TB_LMS_DSCS_PTCP SET
	MDFR_ID = #{mdfrId}
	, MOD_DTTM = FN_DTTM()
	, PROF_MEMO = #{profMemo}
WHERE USER_ID = #{stdId}
	AND DSCS_ID = #{dscsId}

mapper.select:
/*
	SQL ID : DscsJoinUserDAO.getMemo
	설명 : 교수 메모 조회
*/
SELECT
	PROF_MEMO as profMemo
FROM TB_LMS_DSCS_PTCP
WHERE USER_ID = #{stdId}
	AND DSCS_ID = #{dscsId}

/* SQL ID : DscsJoinUserDAO.getSelectCtsLen 설명 : 글자수 조건에 해당하는 토론 참여자 수 조회 */ SELECT COUNT(*) FROM TB_LMS_DSCS_PTCP A LEFT JOIN TB_LMS_DSCS_ATCL B ON (A.DSCS_ID = B.DSCS_ID AND A.USER_ID = B.USER_ID AND B.DELYN = 'N')
LEFT JOIN TB_LMS_DSCS_CMNT C ON (B.DSCS_ATCL_ID = C.DSCS_ATCL_ID AND A.USER_ID = C.USER_ID AND C.DELYN = 'N')
WHERE A.USER_ID = #{stdId} AND A.DSCS_ID = #{dscsId} AND B.ATCL_CTS_LEN >= #{ctsLen}
AND (B.ATCL_CTS_LEN >= #{ctsLen} OR C.CMNT_CTS_LEN >= #{ctsLen})

mapper.update:
/* SQL ID : DscsJoinUserDAO.updateExistingJoinUsers 설명 : 기존 토론 참여자 팀 정보 갱신 */ MERGE INTO TB_LMS_DSCS_PTCP TARGET USING ( SELECT A.USER_ID , B.DSCS_ID /* 1. 팀 ID 추출: 토론(B)의 TEAM_ID와 팀원 테이블(E)을 직접 매칭 */ , (SELECT MAX(E.TEAM_ID) FROM TB_LMS_TEAM_MBR E WHERE E.TEAM_ID = B.TEAM_ID /* B.TEAM_TYCD 대신 B.TEAM_ID 사용 */ AND E.USER_ID = A.USER_ID) AS teamId , #{rgtrId} AS RGTR_ID FROM TB_LMS_ATNDLC A JOIN TB_LMS_DSCS B ON A.SBJCT_ID = B.SBJCT_ID WHERE A.SBJCT_ID = #{sbjctId} AND B.DSCS_ID = #{dscsId} AND A.ATNDLC_STSCD = 'APPROVE' AND B.DELYN = 'N'
AND A.USER_ID = #{stdId}
) SOURCE ON (TARGET.USER_ID = SOURCE.USER_ID AND TARGET.DSCS_ID = SOURCE.DSCS_ID)
WHEN MATCHED THEN UPDATE SET TARGET.TEAM_ID = SOURCE.teamId , TARGET.MDFR_ID = SOURCE.RGTR_ID , TARGET.MOD_DTTM = FN_DTTM()
, TARGET.SCR = 100 , TARGET.EVLYN = 'Y'

/* SQL ID : DscsJoinUserDAO.participateScoreBatch 설명 : 참여 여부 기준 평가 점수 배치 반영 */ MERGE INTO TB_LMS_DSCS_PTCP TARGET USING ( /* 전달된 토론ID가 팀토론 부모이면 모든 자식토론ID를 대상으로 참여형 점수 산정 */ SELECT T.USER_ID , T.DSCS_ID , T.RGTR_ID /* searchKey에 따른 점수 설정 */
, 0 AS NEW_SCR , 100 AS NEW_SCR
FROM ( SELECT P.USER_ID , P.DSCS_ID , #{rgtrId} AS RGTR_ID /* Oracle 11g 서브쿼리 내 참여도 계산 */ , (SELECT COUNT(*) FROM TB_LMS_DSCS_ATCL A WHERE A.DSCS_ID = P.DSCS_ID AND A.RGTR_ID = P.USER_ID AND A.DELYN = 'N') AS atclCnt FROM TB_LMS_DSCS_PTCP P JOIN TB_LMS_DSCS BASE ON BASE.DSCS_ID = #{dscsId} AND BASE.DELYN = 'N' JOIN TB_LMS_DSCS D ON D.DSCS_ID = P.DSCS_ID AND D.DELYN = 'N' WHERE P.DELYN = 'N'
AND D.SBJCT_ID = #{sbjctId}
AND ( (NVL(BASE.DSCS_UNIT_TYCD, 'GNRL') != 'TEAM' AND BASE.UP_DSCS_ID IS NULL AND D.DSCS_ID = BASE.DSCS_ID) OR (BASE.DSCS_UNIT_TYCD = 'TEAM' AND BASE.UP_DSCS_ID IS NULL AND D.UP_DSCS_ID = BASE.DSCS_ID) OR (BASE.UP_DSCS_ID IS NOT NULL AND D.DSCS_ID = BASE.DSCS_ID) ) ) T
WHERE T.atclCnt = 0
WHERE T.atclCnt > 0
) SOURCE ON (TARGET.USER_ID = SOURCE.USER_ID AND TARGET.DSCS_ID = SOURCE.DSCS_ID) /* 참여자 row는 사전 생성되므로 UPDATE만 수행 */ WHEN MATCHED THEN UPDATE SET TARGET.SCR = SOURCE.NEW_SCR , TARGET.EVLYN = 'Y' , TARGET.MDFR_ID = SOURCE.RGTR_ID , TARGET.MOD_DTTM = FN_DTTM()

mapper.select:
/* SQL ID : DscsJoinUserDAO.selectStudentsNotInPtcp 설명 : DSCS_PTCP 미등록 학생 목록 조회, 팀토론은 학습자 팀의 자식 토론 ID 반환 */ SELECT A.USER_ID AS stdId , TARGET.DSCS_ID AS dscsId , CASE WHEN BASE.DSCS_UNIT_TYCD = 'TEAM' OR BASE.UP_DSCS_ID IS NOT NULL THEN TM.TEAM_ID ELSE NULL END AS teamId FROM TB_LMS_ATNDLC A /* 입력 토론 ID 기준으로 일반/팀 부모/팀 자식 토론을 판별한다. */ JOIN TB_LMS_DSCS BASE ON BASE.DSCS_ID = #{dscsId} AND BASE.SBJCT_ID = A.SBJCT_ID AND BASE.DELYN = 'N' LEFT JOIN TB_LMS_DSCS PARENT ON PARENT.DSCS_ID = BASE.UP_DSCS_ID AND PARENT.DELYN = 'N' /* 팀토론은 현재 토론의 팀그룹에 속한 학습자 팀을 조회한다. */ LEFT JOIN ( SELECT M.USER_ID , M.TEAM_ID , T.TEAM_GRP_ID FROM TB_LMS_TEAM_MBR M JOIN TB_LMS_TEAM T ON T.TEAM_ID = M.TEAM_ID WHERE (M.USER_ID, M.TEAM_ID) IN ( SELECT MBR.USER_ID , MAX(MBR.TEAM_ID) AS TEAM_ID FROM TB_LMS_TEAM_MBR MBR JOIN TB_LMS_TEAM TM2 ON TM2.TEAM_ID = MBR.TEAM_ID WHERE TM2.TEAM_GRP_ID = ( SELECT NVL(D.TEAM_GRP_ID, PD.TEAM_GRP_ID) FROM TB_LMS_DSCS D LEFT JOIN TB_LMS_DSCS PD ON PD.DSCS_ID = D.UP_DSCS_ID AND PD.DELYN = 'N' WHERE D.DSCS_ID = #{dscsId} AND D.DELYN = 'N' AND ROWNUM = 1 ) GROUP BY MBR.USER_ID ) ) TM ON TM.USER_ID = A.USER_ID /* 저장 대상 DSCS_ID를 확정한다. 일반토론은 원 토론, 팀토론은 팀별 자식 토론을 사용한다. */ JOIN TB_LMS_DSCS TARGET ON TARGET.DELYN = 'N' AND ( (NVL(BASE.DSCS_UNIT_TYCD, 'GNRL') != 'TEAM' AND BASE.UP_DSCS_ID IS NULL AND TARGET.DSCS_ID = BASE.DSCS_ID) OR (BASE.DSCS_UNIT_TYCD = 'TEAM' AND BASE.UP_DSCS_ID IS NULL AND TARGET.UP_DSCS_ID = BASE.DSCS_ID AND TARGET.TEAM_ID = TM.TEAM_ID) OR (BASE.UP_DSCS_ID IS NOT NULL AND TARGET.DSCS_ID = BASE.DSCS_ID AND TARGET.TEAM_ID = TM.TEAM_ID) ) WHERE A.SBJCT_ID = #{sbjctId} AND A.ATNDLC_STSCD = 'APPROVE' AND A.AUDITYN = 'N'
AND A.USER_ID = #{stdId}
/* 이미 생성된 PTCP row는 제외한다. */
AND A.USER_ID IN
#{item}
AND NOT EXISTS ( SELECT 1 FROM TB_LMS_DSCS_PTCP P WHERE P.USER_ID = A.USER_ID AND P.DSCS_ID = TARGET.DSCS_ID )

mapper.insert:
/* SQL ID : DscsJoinUserDAO.insertDscsJoinUserBatch 설명 : 토론참여자 미등록 학생 일괄 INSERT (PK: DSCS_PTCP_ID IdGenerator 사용) */ INSERT INTO TB_LMS_DSCS_PTCP ( DSCS_PTCP_ID, USER_ID, DSCS_ID, TEAM_ID, RGTR_ID, REG_DTTM, MDFR_ID, MOD_DTTM, DELYN ) SELECT SRC.DSCS_PTCP_ID , SRC.USER_ID , SRC.DSCS_ID , SRC.TEAM_ID , SRC.RGTR_ID , FN_DTTM() , SRC.MDFR_ID , FN_DTTM() , 'N' /* Java IdGenerator로 생성한 PK 목록을 UNION ALL source로 구성한다. */ FROM (
SELECT #{item.dscsPtcpId} AS DSCS_PTCP_ID , #{item.stdId} AS USER_ID , #{item.dscsId} AS DSCS_ID , #{item.teamId} AS TEAM_ID , #{item.rgtrId} AS RGTR_ID , #{item.mdfrId} AS MDFR_ID FROM DUAL
) SRC /* 동시 호출 시 중복 INSERT를 방지한다. */ WHERE NOT EXISTS ( SELECT 1 FROM TB_LMS_DSCS_PTCP P WHERE P.USER_ID = SRC.USER_ID AND P.DSCS_ID = SRC.DSCS_ID )
